"""Create mobile-only, edition-specific user guides from shared instructions."""
from pathlib import Path
from html import escape
root=Path(__file__).resolve().parent.parent
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#e8eae5;color:var(--ink);font-family:Arial,"Noto Sans CJK SC",sans-serif;line-height:1.75}body.magazine{--accent:#273f35;--paper:#f7f5ef;--soft:#e9edde;--ink:#27322b;--muted:#667161;--heading:"Noto Serif CJK SC",serif}body.notebook{--accent:#f04457;--paper:#fff;--soft:#fff0f2;--ink:#27272b;--muted:#66666e;--heading:Arial,"Noto Sans CJK SC",sans-serif;background:#f2f2f4}a{color:inherit}button{font:inherit}main{max-width:430px;margin:auto;background:var(--paper);padding-bottom:88px}header{max-width:430px;margin:auto;background:var(--paper);height:60px;padding:0 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dfe2d7;font-size:13px}header b{color:var(--accent)}header a{font-size:12px;text-decoration:none}h1,h2,h3{font-family:var(--heading);line-height:1.4;margin:0 0 16px}h1{font-size:39px;letter-spacing:-.035em}h2{font-size:27px}h3{font-size:17px}p{font-size:14px;margin:10px 0 16px}small,.caption{font-size:11px;color:var(--muted)}.cover{padding:35px 26px 30px}.issue{font-size:10px;letter-spacing:.12em;color:var(--accent);display:block;margin-bottom:22px}.cover>p{font-size:15px}.scene-image{width:100%;border-radius:18px;margin-top:13px;display:block}.notebook .cover{background:var(--soft)}.notebook h1{font-weight:750}.badge{display:inline-block;padding:5px 12px;border:1px solid var(--accent);border-radius:20px;font-size:11px;color:var(--accent);margin-bottom:18px}.action{display:block;text-align:center;background:var(--accent);color:white;border-radius:12px;padding:13px 18px;text-decoration:none;font-size:14px;min-height:48px;margin:22px 0 8px}.toc{margin:0 22px 22px;border:1px solid #dfe2d7;border-radius:14px;padding:14px 18px;font-size:13px}.toc summary{min-height:30px;color:var(--accent);cursor:pointer}.toc a{display:block;padding:10px 0;min-height:44px;text-decoration:none}.chapter{padding:32px 26px;border-top:1px solid #dfe2d7;scroll-margin-top:12px}.chapter-number{font-size:11px;letter-spacing:.1em;color:var(--accent);margin-bottom:10px;display:block}.steps{list-style:none;padding:0;margin:18px 0;counter-reset:step}.steps li{position:relative;padding:0 0 0 31px;margin:16px 0;font-size:14px;counter-increment:step}.steps li:before{content:counter(step);position:absolute;left:0;top:1px;border-radius:50%;width:22px;height:22px;text-align:center;font-size:12px;background:var(--accent);color:white}.steps b{display:block;margin-bottom:4px}.note{background:var(--soft);border-radius:12px;padding:16px 18px;font-size:13px;margin:18px 0}.note p{font-size:13px;margin:0}.role{border-left:3px solid var(--accent);padding:0 0 0 15px;margin:20px 0}.role b{font-size:14px;color:var(--accent)}.role p{margin:6px 0;font-size:14px}.shot{border:3px solid #dce0d5;border-radius:20px;overflow:hidden;display:block;width:230px;max-width:100%;height:390px;background:var(--paper);padding:0;margin:24px auto 8px;position:relative;cursor:zoom-in}.shot img{width:100%;height:auto;display:block;position:absolute;top:0;left:0}.shot-label{position:absolute;bottom:0;left:0;right:0;background:var(--paper);padding:7px;font-size:10px;color:var(--accent)}.notebook .shot{border-color:#f0dde0}.caption{text-align:center;line-height:1.6}.figure{width:100%;display:block;border-radius:12px}.faq details{border-top:1px solid #dfe2d7;padding:14px 0}.faq summary{font-weight:600;min-height:32px;font-size:14px;cursor:pointer}.faq p{font-size:13px;color:var(--muted);margin:8px 0}.dock{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:min(430px,100%);padding:12px 20px calc(12px + env(safe-area-inset-bottom));background:var(--paper);border-top:1px solid #dfe2d7;display:flex;gap:12px;z-index:10}.dock a{flex:1;text-align:center;min-height:44px;padding:10px 0;border:1px solid var(--accent);border-radius:10px;text-decoration:none;font-size:13px;color:var(--accent)}.dock a:first-child{background:var(--accent);color:white}.credits{font-size:10px;color:var(--muted);padding:18px 26px}dialog{border:0;padding:0;border-radius:14px;max-width:min(96vw,500px);max-height:94dvh;background:var(--paper)}dialog::backdrop{background:#17221cbb}dialog img{width:100%;display:block}dialog button{position:sticky;top:0;float:right;background:var(--paper);border:0;width:48px;height:48px;font-size:28px;cursor:pointer;z-index:1}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:3px}@media(max-width:360px){.cover,.chapter{padding-left:21px;padding-right:21px}h1{font-size:35px}}@page{size:108mm 234mm;margin:0}@media print{html{scroll-behavior:auto}body{background:white;-webkit-print-color-adjust:exact;print-color-adjust:exact}main{max-width:none;width:108mm;margin:0;padding:0}header,.toc,.dock,dialog{display:none!important}.cover,.chapter{break-after:page;break-inside:avoid;min-height:234mm;padding:26px}.chapter:last-of-type{break-after:auto}.credits{display:none}h1{font-size:35px}h2{font-size:26px}.scene-image{max-height:330px;object-fit:cover}.shot{height:285px;width:190px;margin-top:15px}.steps li{margin:12px 0;font-size:13px}p{font-size:13px}.note{font-size:12px;padding:12px}.caption{font-size:10px}.faq summary{font-size:13px}.faq p{font-size:12px}.faq details{padding:6px 0}.faq p{margin:4px 0;line-height:1.6}.chapter .action{margin-top:12px}}
'''
(root/'public/guide/mobile-v0.7.css').write_text(css)

def shot(prefix,name,caption):
 return f'<button class="shot" data-full="./guide/v0.7/{prefix}-{name}.png" aria-label="放大：{escape(caption)}"><img src="./guide/v0.7/{prefix}-{name}.png" alt="{escape(caption)}"/><span class="shot-label">点图看完整页面</span></button><p class="caption">{escape(caption)}</p>'
def steps(items):return '<ol class="steps">'+''.join(f'<li><b>{a}</b>{b}</li>' for a,b in items)+'</ol>'
for slug,name,prefix in [('magazine','A · 杂志版','a'),('notebook','B · 笔记版','b')]:
 chapters=[]
 def chapter(id,number,title,intro,body):
  chapters.append(f'<section class="chapter" id="{id}"><span class="chapter-number">{number} / {escape(name)}</span><h2>{title}</h2><p>{intro}</p>{body}</section>')
 chapter('quick','01','三步，拍出第一张。','不用先学参数，也不用把所有功能都试一遍。',steps([('选一张照片','拍眼前的风景，或选一张想照着拍的参考。'),('两个人各看一句','拿手机的人看取景；镜头前的人看站位和动作。'),('拍下来，再决定','满意就导出；想调整，就选一个地方再拍。')])+shot(prefix,'home','首页的两个入口，任选一个开始。')+'<div class="note">第一次来？首页点「看一个 30 秒示例」，跟着三步体验。示例不会打开相机。</div>')
 chapter('scene','02','风景很好看，人站哪里？','先拍空景，把地面和周围环境也带进去。',steps([('拍或选一张风景','首页点「拍一下眼前的风景」，再点「拍一张或选择风景照片」。'),('选建议，或自己选位置','点 AI 按钮并确认发送；服务未开启时点「我先自己选站位」。'),('选你想留多少风景','人景平衡先试一张；多留风景把人拍小；突出人物把人拍大。')])+shot(prefix,'scene-plan','虚线框表示建议人物位置和大小。')+'<div class="note">图里的框不是现实地面的导航。先确认脚下平坦可站，再开始拍。湖边示例会明确标为示例。</div>')
 chapter('upload','03','喜欢的那张，自己放进来。','每个参考分类，都能上传自己的图片。',steps([('到「找参考」选分类','日常人像、同款打卡、画作复刻都可以。'),('点分类下面的上传按钮','同款点「上传想拍的同款」；画作点「上传想复刻的画作」。'),('相册选图，直接看拍法','参考会归到当前分类，并保留在「我的参考」。')])+shot(prefix,'upload','上传入口就在类别下面，不用回首页找。')+'<div class="note">系统相册取消时保留当前状态。保存失败会告诉你；当前照片仍可继续拍。</div>')
 chapter('references','04','把想拍的图，留给下一次。','「找参考」里切到「我的参考」，就能找回自己上传的图。',steps([('点图看详情','再点「照着这张拍」，回到拍法。'),('点「管理」改名字或分类','改分类后会切到新类别，方便你找到。'),('不需要了，再确认删除','删除参考不会删除已经保存的拍法和照片。')])+shot(prefix,'reference-manage','个人参考可以改名、改分类或删除。')+'<div class="note">个人参考最多 24 张，保存在当前浏览器。收藏保存喜欢的参考；拍摄结果到「我的拍摄」保存。</div>')
 chapter('roles','05','你拿手机，我来站好。','两个人各做一件事，会比一起猜更容易。','<div class="role"><b>拿手机的人</b><p>先看人物在画面里的位置和大小，留出头顶和脚边，再调整背景。</p></div><div class="role"><b>镜头前的人</b><p>先站稳或坐舒服，等同伴框好画面，再试动作。</p></div>'+shot(prefix,'camera','当前最需要做的调整会显示在快门上方。')+'<div class="note">看懂提示后按快门，不必等“完美对齐”。语音提醒由你点「读给对方听」开启。</div>')
 chapter('light','06','光线，也一起照着找。','在「这张怎么拍」展开「光线怎么用」，选择你现场看到的光。',steps([('看人、手机和光的位置','用光图告诉双方站位与背景安排。'),('光线不一样，就按现场条件来','可以借构图，另外选择现场用光。'),('不确定，也能先拍','先保持构图，观察脸部有没有完整亮区。')])+shot(prefix,'light','用光建议包含双方位置和现场注意事项。')+'<div class="note">光影建议帮助你现场判断。相机里的用光入口随时可以再看。</div>')
 chapter('retry','07','下一张，只改一个地方。','拍完先看结果，告诉同伴哪里想保留、哪里想改。',steps([('勾选你想保留的方面','构图、动作、光线或背景。'),('选一个改动','比如人物小一点、动作自然一点或脸再亮一点。'),('点「只改这一点，继续拍」','直接回相机，不用重新选参考。')])+shot(prefix,'review','一次只改一个地方，下一张的目标才清楚。')+'<div class="note">改动和保留项冲突时，会先说明。最近 6 张可切换查看，重要原片记得导出。</div>')
 chapter('save','08','参考、拍法、原片分别留。','三种保存，分别服务不同的下一次。','<div class="role"><b>我的参考</b><p>找回自己上传、想照着拍的图。</p></div><div class="role"><b>我的拍摄</b><p>拍法或结果页点「保存这次拍摄」，留下参考、拍法和明确选中的一张结果。</p></div><div class="role"><b>导出原片</b><p>下载照片到手机，照片里没有辅助线。调色成片另导出，原片保留。</p></div>'+shot(prefix,'mine','「我的拍摄」最多保存 12 次，点记录继续。')+'<p class="caption">参考和拍摄记录保存在当前浏览器。换设备或清理数据前，请导出重要原片。</p>')
 chapter('help','09','遇到问题，先把照片留住。','按对应提示继续，不用重新开始整段流程。','<div class="faq">'+''.join(f'<details open><summary>{a}</summary><p>{b}</p></details>' for a,b in [('相机打不开','允许当前网站使用手机相机；从手机系统浏览器打开体验网址。关闭正在占用相机的应用，再点「重试相机」。'),('参考里没找到人','点「调整人物范围」框住可见人物，再确认。手臂动作需要可靠识别；构图可以先继续。'),('AI 暂未开启或分析失败','照片会保留。你可以自己选站位、看示例，或稍后重试。自己的照片不会被套上示例答案。'),('上传后没找到参考','到「找参考」点「我的参考」，查看当前类别；管理时可以修改分类。'),('保存失败或数量已满','先导出重要原片。个人参考上限24张，拍摄记录上限12次，到对应列表删除旧内容再保存。'),('提示忽然暂停','检查人物是否还在画面里、是否进入多人或被遮挡。切回页面后点「继续拍摄」，也可主动按快门。')])+'</div><a class="action product-link" href="./index.html">回到产品，开始拍</a>')
 toc='<details class="toc"><summary>按你要做的事找步骤</summary>'+''.join(f'<a href="#{id}">{title}</a>' for id,title in [('quick','01 · 三步上手'),('scene','02 · 从风景开始'),('upload','03 · 上传自己的参考'),('references','04 · 找回和管理参考'),('roles','05 · 两个人怎么配合'),('light','06 · 找到好看的光'),('retry','07 · 下一张只改一点'),('save','08 · 保存与导出'),('help','09 · 遇到问题')])+'</details>'
 body=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><meta name="theme-color" content="{'#273f35' if slug=='magazine' else '#f04457'}"/><title>照着拍 · {name}｜手机使用手册</title><link rel="stylesheet" href="./guide/mobile-v0.7.css"/></head><body class="{slug}"><header><b>◉ 照着拍</b><span>{name}</span><a class="product-link" href="./index.html">回产品 ↗</a></header><main><section class="cover" id="cover"><span class="issue">照着拍 / 手机使用手册 v0.7</span><span class="badge">{name}</span><h1>喜欢的那张，<br/>我们一起<br/>拍出来。</h1><p>给拿手机的人，也给镜头前的人。<br/>从一张照片开始，找到共同的拍法。</p><img class="scene-image" src="./images/review/scenarios.png" alt="两位朋友从选参考到一起拍摄和回看的情境示意"/><p class="caption">AI 生成情境示意 · 下面用真实界面讲步骤</p><a class="action" href="#quick">30 秒上手 →</a></section>{toc}{''.join(chapters)}<p class="credits">截图来自照着拍 v0.7 的 {name}。相机与结果截图用受控视频流展示操作；实际使用为手机相机。2026 年 10 月。</p></main><nav class="dock" aria-label="手册操作"><a class="product-link" href="./{'index.html' if slug=='magazine' else 'notebook.html'}">回到产品</a><a href="./guide/{slug}-handbook-v0.7.pdf" download="{slug}-handbook-v0.7.pdf">下载 PDF ↓</a></nav><dialog id="image-viewer"><button aria-label="关闭大图">×</button><img alt="完整产品页面"/></dialog><script>const dialog=document.querySelector('#image-viewer');document.querySelectorAll('[data-full]').forEach(button=>button.onclick=()=>{{dialog.querySelector('img').src=button.dataset.full;dialog.showModal();}});dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclick=e=>{{if(e.target===dialog)dialog.close();}};</script></body></html>'''
 if slug=='notebook':body=body.replace('class="product-link" href="./index.html"','class="product-link" href="./notebook.html"')
 (root/'public'/f'{slug}-guide.html').write_text(body)
(root/'public/handbook.html').write_text('''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>照着拍 · 选择手册</title><body style="font-family:sans-serif;max-width:430px;margin:auto;padding:32px;line-height:2"><h1>你使用哪一版？</h1><p><a href="./magazine-guide.html">A · 杂志版使用手册 →</a></p><p><a href="./notebook-guide.html">B · 笔记版使用手册 →</a></p><script>const theme=new URLSearchParams(location.search).get('theme');if(theme)location.replace(theme==='notebook'?'./notebook-guide.html':'./magazine-guide.html');</script></body></html>''')
print('Created two independent mobile user guides and a guide selector.')
